/* Eduqas GCSE Media Studies — grade-separated exam-style questions.
   Each question: { g: grade 4-9, marks, q, scheme: [mark points], answer } */
export default {
  subjectId: "media-studies",
  sections: {
    "The theoretical framework": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "Name the four areas of the theoretical framework.", scheme: ["Media language, representation, media industries, audiences"], answer: "Media language, representation, media industries and audiences." },
      { g: 4, marks: 1, q: "What is 'media language'?", scheme: ["The way media products use codes and conventions to communicate meaning"], answer: "The way media products use codes and conventions to create and communicate meaning." },
      { g: 4, marks: 1, q: "What is 'representation'?", scheme: ["How the media portray people, places, events, ideas or groups"], answer: "How the media portray people, places, events, ideas and groups." },
      { g: 4, marks: 1, q: "What is a stereotype?", scheme: ["A simplified, widely held (often exaggerated) idea about a group of people"], answer: "A simplified and widely held idea about a particular group of people." },
      { g: 4, marks: 1, q: "What is an 'audience' in media studies?", scheme: ["The people who receive/consume a media product"], answer: "The people who consume or receive a media product." },
      { g: 4, marks: 1, q: "What is a 'target audience'?", scheme: ["The specific group a media product is aimed at"], answer: "The specific group of people a media product is aimed at." },
      { g: 4, marks: 1, q: "What is 'genre'?", scheme: ["A type or category of media product (e.g. horror, sci-fi)"], answer: "A type or category of media product, such as horror or science fiction." },
      { g: 4, marks: 1, q: "What is a 'convention'?", scheme: ["A common/expected feature of a media product or genre"], answer: "A feature that is commonly expected in a particular type or genre of media product." },
      { g: 4, marks: 1, q: "What is a 'code' in media language?", scheme: ["A system of signs that communicates meaning (technical, symbolic or written)"], answer: "A system of signs — technical, symbolic or written — that communicates meaning." },
      { g: 4, marks: 1, q: "What is a media industry?", scheme: ["A company/organisation that produces and distributes media products"], answer: "A company or organisation that produces and distributes media products." },
      { g: 4, marks: 1, q: "What does a media regulator do?", scheme: ["Controls/monitors media products to ensure they follow rules"], answer: "It monitors and controls media products to make sure they follow the rules." },
      { g: 4, marks: 1, q: "Name a UK media regulator.", scheme: ["Ofcom / BBFC / ASA / IPSO (any one)"], answer: "Ofcom (also the BBFC or ASA)." },
      { g: 4, marks: 1, q: "What are 'demographics'?", scheme: ["Groups defined by measurable factors such as age, gender, income"], answer: "Groups of people defined by measurable factors such as age, gender and income." },
      { g: 4, marks: 1, q: "Who developed the Uses and Gratifications theory?", scheme: ["Blumler and Katz"], answer: "Blumler and Katz." },
      { g: 4, marks: 1, q: "What is 'narrative'?", scheme: ["The way a story is structured/told in a media product"], answer: "The way a story is structured and told in a media product." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 1, q: "Give an example of a technical code.", scheme: ["Any one: camera angle/shot, lighting, editing, sound"], answer: "A camera angle or shot (also lighting, editing or sound)." },
      { g: 5, marks: 1, q: "Give an example of a symbolic code.", scheme: ["Any one: mise-en-scène, colour, body language, props, costume"], answer: "Colour (also mise-en-scène, body language, props or costume)." },
      { g: 5, marks: 2, q: "Explain the difference between denotation and connotation.", scheme: ["Denotation = the literal/obvious meaning of a sign", "Connotation = the associated/implied meaning"], answer: "Denotation is the literal meaning of a sign, while connotation is the implied or associated meaning it suggests." },
      { g: 5, marks: 1, q: "What does 'mise-en-scène' mean?", scheme: ["Everything within the frame: setting, costume, props, lighting, actors"], answer: "Everything placed within the frame — the setting, costume, props, lighting and actors." },
      { g: 5, marks: 2, q: "State the difference between demographics and psychographics.", scheme: ["Demographics: measurable groups (age, gender, income)", "Psychographics: lifestyle, attitudes, values and interests"], answer: "Demographics group audiences by measurable factors like age and gender, while psychographics group them by lifestyle, attitudes and values." },
      { g: 5, marks: 1, q: "Define a media 'conglomerate'.", scheme: ["A large company that owns many other (smaller) companies"], answer: "A large company that owns many other, often smaller, companies." },
      { g: 5, marks: 1, q: "What is vertical integration?", scheme: ["When a company owns different stages of production and distribution"], answer: "When a single company owns several stages of production and distribution of a media product." },
      { g: 5, marks: 2, q: "State two of the four needs in Uses and Gratifications theory.", scheme: ["Any two: information, personal identity, social interaction, entertainment/diversion"], answer: "Information and entertainment (also personal identity and social interaction)." },
      { g: 5, marks: 1, q: "What is a 'preferred reading' (Stuart Hall)?", scheme: ["The meaning the producer intends/prefers the audience to take"], answer: "The meaning the producer intends and hopes the audience will take from the product." },
      { g: 5, marks: 1, q: "What is public service broadcasting?", scheme: ["Broadcasting that aims to inform, educate and entertain (e.g. the BBC)"], answer: "Broadcasting that aims to inform, educate and entertain the public, such as the BBC." },
      { g: 5, marks: 1, q: "What does the BBFC do?", scheme: ["Classifies films/videos by age rating"], answer: "It classifies films and videos with age ratings (such as PG, 12, 15, 18)." },
      { g: 5, marks: 1, q: "State the two broad ways audiences can respond to media.", scheme: ["Actively or passively"], answer: "Actively or passively." },
      { g: 5, marks: 1, q: "What is meant by 'selection and construction' in representation?", scheme: ["Producers choose what to include/leave out and arrange it to create a viewpoint"], answer: "Producers select what to include or leave out and construct it to create a particular viewpoint." },
      { g: 5, marks: 2, q: "Name two media forms.", scheme: ["Any two: TV, film, radio, newspapers, magazines, advertising, music video, video games, online/social media"], answer: "Television and advertising (also film, radio, newspapers, magazines, music video, video games and online media)." },
      { g: 5, marks: 1, q: "What is a 'star image'?", scheme: ["The constructed public identity/persona of a celebrity used to sell products"], answer: "The carefully constructed public identity or persona of a celebrity, used to promote products." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Explain how a camera shot can create meaning, using an example.", scheme: ["Names a shot and its effect", "e.g. a close-up shows emotion/importance; a long shot shows setting/isolation"], answer: "A close-up focuses on a character's face to show their emotion, making the audience feel closer to them, while a long shot can make a character look small or isolated in their surroundings." },
      { g: 6, marks: 2, q: "Explain how colour can be used as a symbolic code.", scheme: ["Colour carries connotations", "e.g. red connotes danger/passion; guides how the audience reads the image"], answer: "Colour carries connotations that shape meaning — for example red can suggest danger or passion — guiding how the audience interprets an image or character." },
      { g: 6, marks: 2, q: "Explain how genre conventions help audiences.", scheme: ["They set up expectations of the product", "Helping audiences understand and choose products they will enjoy"], answer: "Genre conventions set up expectations, so audiences know what to expect and can more easily understand and choose products they are likely to enjoy." },
      { g: 6, marks: 2, q: "Explain how a media product might reinforce a stereotype.", scheme: ["Repeatedly showing a group in a limited/typical way", "Presenting it as normal, so the stereotype is strengthened"], answer: "A product reinforces a stereotype by repeatedly showing a group in the same limited, typical way and presenting it as normal, so the audience's existing view is strengthened." },
      { g: 6, marks: 2, q: "Explain how a media product might challenge a stereotype.", scheme: ["Showing a group in a non-typical/positive/complex way", "Going against what the audience expects"], answer: "A product challenges a stereotype by showing a group in a non-typical, positive or more complex way, going against what audiences usually expect." },
      { g: 6, marks: 3, q: "Explain the Uses and Gratifications theory with examples.", scheme: ["Blumler and Katz: audiences actively use media to satisfy needs", "Information/education; personal identity; social interaction; entertainment/diversion", "An example for at least one need"], answer: "Blumler and Katz argue audiences actively use media to satisfy needs: information (a news app), personal identity (relating to a character), social interaction (discussing a show) and entertainment or escapism (watching a film to relax)." },
      { g: 6, marks: 2, q: "Explain vertical integration and one benefit to a company.", scheme: ["The company owns production and distribution (different stages)", "Benefit: more control / keeps more profit / promotes its own products"], answer: "Vertical integration is when a company owns several stages such as production and distribution, which gives it more control over its products and lets it keep more of the profit." },
      { g: 6, marks: 2, q: "Explain why media products are aimed at specific audiences.", scheme: ["To make the product appeal strongly to that group", "To maximise sales/viewers and advertising revenue"], answer: "Products are targeted so they strongly appeal to a particular group, which maximises sales or viewing figures and the advertising revenue they can earn." },
      { g: 6, marks: 3, q: "Explain Todorov's narrative theory.", scheme: ["Equilibrium (balance/normality)", "Disruption to the equilibrium", "Recognition and repair of the disruption", "New equilibrium restored"], answer: "Todorov suggests narratives begin with an equilibrium (normality), which is disrupted; the characters recognise the disruption and act to repair it, leading to a new equilibrium at the end." },
      { g: 6, marks: 3, q: "Explain Stuart Hall's three types of audience reading.", scheme: ["Preferred/dominant: audience accepts the intended meaning", "Negotiated: audience partly accepts, partly questions it", "Oppositional: audience rejects the intended meaning"], answer: "Hall identifies a preferred reading, where the audience accepts the intended meaning; a negotiated reading, where they partly agree but also question it; and an oppositional reading, where they reject the intended meaning." },
      { g: 6, marks: 2, q: "Explain why media regulation is important.", scheme: ["Protects audiences from harmful/unsuitable content", "e.g. age ratings, standards on accuracy/offence"], answer: "Regulation protects audiences from harmful or unsuitable content — for example age ratings on films and standards preventing offensive or misleading material." },
      { g: 6, marks: 2, q: "Explain how selection and construction can create bias in a news story.", scheme: ["Choosing which facts/images to include or leave out", "Angle/language used creates a particular viewpoint/bias"], answer: "By choosing which facts and images to include or leave out and the language and angle used, a news producer constructs a particular viewpoint, which can create bias." },
      { g: 6, marks: 2, q: "Explain how mise-en-scène communicates meaning in a scene.", scheme: ["Setting, costume, lighting and props are chosen deliberately", "They create atmosphere and connotations that guide the audience"], answer: "The setting, costume, lighting and props are deliberately chosen to create atmosphere and connotations — for example a dark, cluttered room can suggest danger — guiding how the audience reads the scene." },
      { g: 6, marks: 2, q: "Explain how ownership can affect media content (Curran and Seaton).", scheme: ["Concentrated ownership by a few conglomerates", "Can reduce variety/diversity of views produced"], answer: "Curran and Seaton argue that when ownership is concentrated in a few large conglomerates, the range of views and variety of content can be reduced, as owners pursue profit and their own interests." },
      { g: 6, marks: 2, q: "Explain the difference between an active and a passive audience.", scheme: ["Active: audiences interpret/respond and make their own meaning", "Passive: audiences simply accept/absorb the message"], answer: "An active audience interprets media and makes its own meanings, while a passive audience is seen as simply accepting and absorbing the messages they are given." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 4, q: "Analyse how a technical code and a symbolic code might combine to create meaning in a film poster or advert.", scheme: ["Names a technical code and its effect (e.g. lighting/camera)", "Names a symbolic code and its effect (e.g. colour/facial expression)", "Explains how they combine to create a specific meaning", "Links to the intended audience response"], answer: "Low-key lighting (a technical code) could create dark shadows while a character's tense facial expression and dark costume (symbolic codes) suggest threat. Combined, they create a menacing meaning that positions the audience to expect danger, suiting a thriller." },
      { g: 7, marks: 4, q: "Explain how a media product constructs the representation of a particular group, referring to media language.", scheme: ["Identifies the group and how it is represented", "Uses at least two codes (e.g. costume, camera, setting)", "Explains the meaning created", "Notes it is a construction/selection, not reality"], answer: "A product might represent teenagers as rebellious through costume (hoodies), setting (street corners) and camera angles that make them look imposing. These choices construct a particular, selected image rather than showing the whole reality of the group." },
      { g: 7, marks: 3, q: "Explain how the Uses and Gratifications theory could apply to a named media product.", scheme: ["Applies at least two needs to the product", "e.g. a soap opera: entertainment/diversion and social interaction", "Explains how the product meets those needs"], answer: "For a soap opera, audiences might watch for entertainment and escapism from their own lives, and for social interaction as they discuss the storylines with others, so the product satisfies several Uses and Gratifications needs." },
      { g: 7, marks: 4, q: "Explain how Stuart Hall's reception theory can explain different responses to the same product.", scheme: ["Preferred: audience shares the producer's values → accepts message", "Negotiated: audience agrees in part but adapts it to their own view", "Oppositional: audience with different values rejects the message", "Response depends on the audience's own background/beliefs"], answer: "The same advert could be read differently: an audience sharing its values takes the preferred reading and accepts its message; others partly agree but adapt it (negotiated); and audiences with opposing values reject it entirely (oppositional). The response depends on each audience member's own beliefs and background." },
      { g: 7, marks: 3, q: "Explain how a media conglomerate uses integration to reach its audiences.", scheme: ["Owns production and distribution (vertical) / different media (horizontal)", "Can promote products across its platforms (cross-media)", "Reaches larger audiences and increases profit"], answer: "A conglomerate that owns both production companies and distribution channels can make a product and control how it reaches audiences, and by owning several media it can cross-promote across its platforms, reaching larger audiences and increasing profit." },
      { g: 7, marks: 3, q: "Explain how regulation by a body such as Ofcom or the BBFC affects a specific type of product.", scheme: ["Names the regulator and what it controls", "e.g. BBFC age-rates films, affecting content/who can watch", "Producers must follow rules or edit content"], answer: "The BBFC gives films age ratings, so producers must consider the content they include to achieve the rating they want; strong content may be cut to reach a wider audience, showing how regulation shapes the final product." },
      { g: 7, marks: 3, q: "Explain how genre and narrative work together in a media product.", scheme: ["Genre sets conventions/expectations", "Narrative structures the story (e.g. Todorov)", "Genre conventions shape the type of disruption/resolution audiences expect"], answer: "Genre provides the conventions audiences expect, while narrative structures the story — for example a crime drama (genre) follows a disruption (a crime) and its resolution (solving it), so the genre shapes the kind of narrative events the audience anticipates." },
      { g: 7, marks: 3, q: "Explain how a media product targets and appeals to its intended audience.", scheme: ["Identifies the target audience (demographic/psychographic)", "Explains techniques used (content, style, language, platform)", "Links these to the audience's interests/needs"], answer: "A product aimed at young adults might use fast editing, trending music and social-media platforms, with content reflecting their interests and values, so the style and distribution are matched to the target audience's tastes and habits." },
      { g: 7, marks: 3, q: "Explain how bias can be created in a newspaper through media language.", scheme: ["Choice of headline/language (emotive or loaded words)", "Choice/framing of images", "Selection of which facts to include, creating a viewpoint"], answer: "A newspaper can create bias through emotive headlines and loaded language, carefully chosen images, and by selecting which facts to report, all of which build a particular viewpoint rather than a neutral account." },
      { g: 7, marks: 3, q: "Explain how online and digital distribution has changed the way audiences consume media.", scheme: ["On-demand/streaming — watch anytime, any device", "Audiences can interact/share/produce content (prosumers)", "More choice and control than traditional scheduled media"], answer: "Digital distribution lets audiences stream content on demand on any device, interact with and share it, and even create their own, giving them far more choice and control than traditional scheduled broadcasting." },
      { g: 7, marks: 3, q: "Explain how Barthes' idea of signs (denotation and connotation) helps analyse an advert.", scheme: ["Denotation: what is literally shown", "Connotation: the meanings/associations it suggests", "Applying both reveals the advert's intended message"], answer: "Barthes' theory lets us read an advert on two levels: the denotation is what is literally shown (e.g. a watch), and the connotation is what it suggests (luxury, success). Analysing both reveals the intended message the advert is selling." },
      { g: 7, marks: 3, q: "Explain how a representation might reflect the social or cultural context in which it was made.", scheme: ["Products reflect the attitudes/values of their time", "Older products may show dated attitudes; newer ones more diverse", "Context shapes how a group is represented"], answer: "Representations reflect the attitudes of the time they were made — for example older media may show dated gender roles, while more recent products often show more diverse and equal representations, reflecting changing social attitudes." },
      { g: 7, marks: 3, q: "Explain how a product's funding model (public service vs commercial) can influence its content.", scheme: ["Public service (e.g. BBC): funded by licence fee → must inform/educate/entertain, no adverts, broad range", "Commercial: funded by advertising → aims for large audiences/profit", "Funding shapes the type of content produced"], answer: "A public service broadcaster funded by the licence fee must inform, educate and entertain with no adverts, so it makes a broad range of content, whereas a commercial broadcaster relies on advertising and so aims for large audiences and profit, which shapes the content it produces." },
      { g: 7, marks: 3, q: "Explain how celebrity or 'star image' is constructed and used in the media.", scheme: ["Built through media appearances, image, publicity", "Carefully managed to appeal to fans", "Used to sell products/promote media (audience appeal)"], answer: "A star image is constructed through carefully managed appearances, styling and publicity to create an appealing persona, which is then used to attract fans and sell or promote media products." },
      { g: 7, marks: 3, q: "Explain, with examples, how the same audience can be both active and passive.", scheme: ["Active: sometimes interpret/challenge/discuss media", "Passive: sometimes absorb media without questioning", "Depends on the situation/product/attention"], answer: "An audience can be active when they analyse or debate a documentary and form their own views, but passive when they watch light entertainment without questioning it, so how they respond depends on the product and how much attention they give it." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "Analyse and evaluate how media language is used to construct meaning in a media product you have studied.", scheme: ["Identifies several codes/conventions used", "Explains the meanings they create", "Links to genre/audience positioning", "Evaluates how effectively meaning is constructed"], answer: "The product uses codes such as lighting, camera angles, colour and mise-en-scène to construct meaning — for example dark lighting and low angles create threat. These match its genre conventions and position the audience to respond in a particular way, and overall the media language works effectively to guide the audience's interpretation." },
      { g: 8, marks: 4, q: "Evaluate how far a media product reinforces or challenges stereotypes.", scheme: ["Identifies stereotypes present and how reinforced (codes)", "Identifies where it challenges them", "Considers audience readings", "Balanced, justified judgement"], answer: "The product reinforces some stereotypes through familiar codes of costume and behaviour, but it also challenges others by presenting characters in complex, non-typical ways. Different audiences may read this differently, so overall it both reinforces and challenges stereotypes rather than doing only one." },
      { g: 8, marks: 4, q: "Evaluate the usefulness of the Uses and Gratifications theory for understanding audiences.", scheme: ["Strength: recognises audiences are active and use media for needs", "Strength: explains why people choose certain products", "Weakness: assumes audiences always know their motives; may oversimplify", "Balanced judgement"], answer: "Uses and Gratifications is useful because it treats audiences as active, explaining why they choose products to meet needs such as entertainment or information. However, it assumes audiences always know their own motives and can oversimplify, ignoring how media might influence them, so it is helpful but not a complete explanation." },
      { g: 8, marks: 4, q: "Analyse how ownership and industry context shape a media product, referring to Curran and Seaton.", scheme: ["Curran and Seaton: concentration of ownership affects variety", "Owner's aims (profit/interests) influence content", "Larger companies have resources for high production values", "Effect on the range of views/products"], answer: "Curran and Seaton argue that concentrated ownership shapes content, as large conglomerates pursue profit and their own interests, which can narrow the range of views. At the same time their resources allow high production values, so ownership affects both the variety and the quality of the products audiences receive." },
      { g: 8, marks: 4, q: "Evaluate how effective media regulation is at protecting audiences.", scheme: ["Regulators (Ofcom/BBFC/ASA) set standards/age ratings", "Protects from harmful/offensive/misleading content", "Limitations: hard to regulate online/global content; audiences can bypass", "Balanced judgement"], answer: "Regulators such as Ofcom and the BBFC set standards and age ratings that protect audiences from harmful, offensive or misleading content. However, online and global content is much harder to regulate and audiences can bypass restrictions, so regulation is effective for traditional media but increasingly limited online." },
      { g: 8, marks: 4, q: "Analyse how a media product positions its audience to take a preferred reading.", scheme: ["Identifies the intended (preferred) message", "Explains techniques used to encourage it (codes, narrative)", "Considers how audience values affect acceptance", "Judgement on how successfully it positions the audience"], answer: "The product uses selected images, sympathetic camerawork and emotive language to encourage the audience to accept its intended message. Audiences who share its values are likely to take this preferred reading, though those with different values may negotiate or oppose it, so it positions but does not guarantee the response." },
      { g: 8, marks: 4, q: "Evaluate the impact of digital convergence on media industries.", scheme: ["Convergence: media/technologies combine (one device, many forms)", "Industries reach audiences on many platforms; new revenue (streaming)", "Challenges: piracy, competition, need to adapt distribution", "Balanced judgement"], answer: "Digital convergence lets audiences access many media forms on one device, so industries can reach them across multiple platforms and earn from streaming and downloads. However, it also brings piracy, greater competition and pressure to change how products are distributed, so it offers opportunities but also serious challenges." },
      { g: 8, marks: 4, q: "Analyse the representation of an event or issue in a media product and explain its likely effect on the audience.", scheme: ["Describes how the event/issue is represented (codes, selection)", "Explains the viewpoint constructed", "Explains the likely effect on the audience's understanding/attitude", "Notes representation is constructed, not neutral"], answer: "The product represents the issue through selected images and language that construct a clear viewpoint, for example emphasising one side. This is likely to shape the audience's understanding and attitude towards the issue, and because it is a construction rather than a neutral account, it can influence how the audience thinks." },
      { g: 8, marks: 4, q: "Evaluate the active versus passive audience debate.", scheme: ["Passive view (e.g. effects/hypodermic): audiences absorb messages directly", "Active view (Uses and Gratifications, Hall): audiences interpret and choose", "Evidence for each side", "Balanced judgement — audiences vary"], answer: "The passive view, such as the hypodermic model, suggests audiences directly absorb media messages, while active theories like Uses and Gratifications and Hall's reception theory show audiences interpret and choose media for themselves. In reality audiences are neither wholly active nor passive; how they respond varies with the product, situation and individual." },
      { g: 8, marks: 4, q: "Analyse how a narrative theory applies to a product and evaluate its limitations.", scheme: ["Applies a theory (e.g. Todorov equilibrium–disruption–resolution)", "Shows how the product fits", "Limitation: not all narratives are linear/resolved (e.g. soaps, multi-strand)", "Balanced judgement"], answer: "Todorov's theory fits many products that move from equilibrium through disruption to a new equilibrium, such as a film with a clear resolution. However, it is limited because some narratives, like ongoing soaps or multi-strand dramas, never fully resolve, so the theory does not apply to every product." },
      { g: 8, marks: 4, q: "Evaluate how far social and political context influences the representations in a media product.", scheme: ["Products reflect the attitudes/laws of their time", "Examples of context shaping representation (e.g. changing gender roles)", "But producers can also challenge context", "Balanced judgement"], answer: "Media representations are strongly influenced by their social and political context, reflecting the attitudes and laws of the time, such as more diverse representations today than in the past. However, some producers deliberately challenge their context, so while context shapes representation it does not entirely determine it." },
      { g: 8, marks: 3, q: "Analyse how genre hybridity is used in a product and explain its effect.", scheme: ["Identifies two genres combined", "Explains why (appeal to more audiences/freshness)", "Effect on audience expectations"], answer: "A product might combine comedy and horror, mixing the conventions of both. This can attract fans of each genre and feel fresh, while playing with the audience's expectations of what should happen." },
      { g: 8, marks: 4, q: "Evaluate the role of public service broadcasting in the modern media landscape.", scheme: ["PSB informs, educates, entertains; wide range; caters for minorities", "Value: quality, impartial news, universal access", "Challenges: competition from streaming, funding (licence fee) debate", "Balanced judgement"], answer: "Public service broadcasting informs, educates and entertains, providing impartial news and a wide range of content including for minority audiences. It is valued for quality and universal access, but faces strong competition from streaming services and debate over its licence-fee funding, so its role is important but increasingly challenged." },
      { g: 8, marks: 3, q: "Analyse how advertising uses media language to persuade its audience.", scheme: ["Uses codes: images, colour, slogans, celebrity/aspiration", "Creates connotations (e.g. success, happiness)", "Positions the audience to want the product"], answer: "Advertising uses persuasive media language — striking images, colour, memorable slogans and aspirational or celebrity figures — to create positive connotations such as success or happiness, positioning the audience to associate these feelings with the product and want to buy it." },
      { g: 8, marks: 4, q: "Evaluate how audience feedback and participation have changed media in the digital age.", scheme: ["Audiences can comment, share, rate, create content", "Producers respond to feedback / audiences shape content", "Concerns: misinformation, pressure, echo chambers", "Balanced judgement"], answer: "In the digital age audiences can comment on, share, rate and even create media, so producers increasingly respond to feedback and audiences help shape content. However, this also brings misinformation, online pressure and echo chambers, so audience participation has empowered audiences but also created new problems." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "\"Media products always reinforce dominant ideologies.\" Evaluate this statement using representation and relevant theory.", scheme: ["Explains dominant ideology and how media can reinforce it (selection, stereotypes)", "Gives examples of reinforcement", "Counter: some products challenge dominant ideologies", "Reference to theory (e.g. Hall's readings, representation)", "Considers audience interpretation (oppositional readings)", "Balanced, justified conclusion"], answer: "Many products do reinforce dominant ideologies through selective representations and stereotypes that present certain values as normal, and Hall's preferred reading shows how audiences are positioned to accept them. However, some products deliberately challenge dominant ideologies, and audiences can take oppositional readings, so the statement is too absolute — media often reinforce dominant ideologies but do not always do so." },
      { g: 9, marks: 6, q: "Evaluate how useful reception theory (Stuart Hall) is for understanding how audiences respond to media.", scheme: ["Explains preferred, negotiated and oppositional readings", "Strength: recognises audiences are active and diverse", "Strength: explains why the same product is read differently", "Weakness: categories can be simplistic; ignores degrees of response", "Balanced judgement"], answer: "Reception theory is useful because it recognises audiences are active and diverse, explaining why the same product produces preferred, negotiated and oppositional readings depending on people's values. However, the three categories can be simplistic and don't capture every shade of response, so it is a valuable but not complete model of how audiences respond." },
      { g: 9, marks: 6, q: "Analyse and evaluate how media language, representation, industry and audience interrelate in a media product you have studied.", scheme: ["Media language creates meaning through codes", "This constructs particular representations", "Industry context (ownership/funding/regulation) shapes the product", "Audience is targeted and responds (readings)", "Shows how the four areas connect", "Evaluative, coherent judgement"], answer: "In the product, media language such as camerawork and mise-en-scène constructs particular representations of characters and issues; the industry context — its ownership, funding and regulation — shapes what could be produced; and the product is targeted at a specific audience who respond with preferred, negotiated or oppositional readings. The four areas are therefore interlinked: industry conditions and media language shape the representations, which in turn are interpreted by the intended audience." },
      { g: 9, marks: 6, q: "Evaluate the extent to which media ownership shapes what audiences see and hear (refer to Curran and Seaton).", scheme: ["Curran and Seaton: ownership concentration reduces diversity/pursues profit", "Owners' interests can influence content/news", "Counter: internet/independent producers increase choice", "Regulation can limit owner power", "Audiences can seek alternative sources", "Balanced, justified conclusion"], answer: "Curran and Seaton argue that concentrated ownership shapes content, as powerful owners pursue profit and their own interests, which can narrow the range of views, especially in news. However, the internet and independent producers give audiences far more choice, regulation limits owners' power, and audiences can seek alternative sources, so ownership strongly influences but does not entirely control what audiences see." },
      { g: 9, marks: 6, q: "Evaluate how effective media regulation can be in a changing digital landscape.", scheme: ["Regulators set standards, age ratings, protect audiences", "Effective for broadcast/print/cinema", "Digital/global/user-generated content very hard to regulate", "Attempts (platform rules, laws) but enforcement difficult", "Audiences can bypass restrictions", "Balanced conclusion"], answer: "Regulation is effective for traditional broadcast, print and cinema, where regulators set clear standards and age ratings that protect audiences. However, the global, digital and user-generated nature of online media makes it very hard to regulate; platform rules and new laws help but are difficult to enforce and audiences can bypass restrictions, so regulation is increasingly limited in the digital landscape." },
      { g: 9, marks: 6, q: "\"Audiences are more powerful than ever.\" Evaluate this statement with reference to media theory and the digital age.", scheme: ["For: audiences create/share content, give feedback, choose on demand (active)", "Reception/Uses and Gratifications support active audiences", "Against: powerful conglomerates still control much content", "Algorithms/data shape what audiences see", "Misinformation limits genuine choice", "Balanced, justified conclusion"], answer: "Audiences are arguably more powerful, as digital media let them create and share content, give feedback and choose on demand, supporting active-audience theories. However, large conglomerates still control much content, algorithms and data shape what people see, and misinformation limits genuine choice, so audiences have gained real power but are still influenced and constrained by the industry." },
      { g: 9, marks: 6, q: "Analyse how the context of a media product shapes both its media language and its representations.", scheme: ["Context: social, political, historical, cultural circumstances", "Shapes the codes/conventions used (e.g. technology, style of the time)", "Shapes which representations are acceptable/expected", "Examples linking context to language and representation", "Evaluative judgement"], answer: "A product's social, political and historical context shapes it strongly: the technology and style of the time influence the media language available, and the attitudes of the era shape which representations are expected or acceptable — for example changing gender attitudes lead to different representations. Context therefore shapes both how a product looks and who and what it portrays, though producers can still respond to or challenge that context." },
      { g: 9, marks: 5, q: "Evaluate the value of semiotic analysis (Barthes) for understanding media products.", scheme: ["Barthes: signs have denotation and connotation; myths", "Strength: reveals hidden/implied meanings and ideology", "Strength: applies to all visual media", "Weakness: connotations can be subjective; different audiences read differently", "Balanced judgement"], answer: "Semiotic analysis is valuable because it uncovers the connotations and myths behind the literal denotation of signs, revealing implied meanings and ideology in any visual media. However, connotations can be subjective and different audiences may read the same signs differently, so semiotics is a powerful tool but its readings are not fixed or objective." },
      { g: 9, marks: 6, q: "Evaluate the claim that stereotypes are a necessary part of media products.", scheme: ["For: quick shorthand; help audiences understand characters fast (limited time)", "Aid genre recognition", "Against: can be harmful, misleading, offensive; reinforce prejudice", "Products can challenge stereotypes successfully", "Balanced, justified conclusion"], answer: "Stereotypes can be seen as necessary because they act as a quick shorthand, helping audiences understand characters instantly in limited time and aiding genre recognition. However, they can be misleading, harmful and reinforce prejudice, and many products successfully create rounded characters without them, so stereotypes are useful but not truly necessary and should be used critically." },
      { g: 9, marks: 6, q: "Analyse how industry factors such as funding, regulation and ownership affect a specific media product.", scheme: ["Funding model (public/commercial) shapes content and aims", "Regulation shapes what content is allowed (age rating/standards)", "Ownership shapes resources and editorial influence", "Links each factor to the actual product", "Evaluative conclusion"], answer: "A product's funding model shapes its aims — a licence-fee broadcaster must inform and educate, while a commercial one chases audiences for advertising. Regulation limits the content it can include through standards and ratings, and its ownership affects its resources and any editorial influence from the owner. Together these industry factors clearly shape what the product is and can contain." },
      { g: 9, marks: 6, q: "Compare and evaluate the Uses and Gratifications theory and reception theory as explanations of audience behaviour.", scheme: ["Uses and Gratifications: audiences choose media to meet needs (active)", "Reception theory: audiences decode meaning (preferred/negotiated/oppositional)", "Both see audiences as active", "U&G explains why they choose; reception explains how they interpret", "Limitations of each", "Balanced judgement on usefulness"], answer: "Both theories treat audiences as active: Uses and Gratifications explains why people choose media — to meet needs such as entertainment or identity — while reception theory explains how they interpret it through preferred, negotiated or oppositional readings. U&G can assume people know their motives, and reception theory can be simplistic, so the two are best used together, one explaining audience choice and the other audience interpretation." },
      { g: 9, marks: 6, q: "Analyse how representation in a media product can construct identity and reflect power in society.", scheme: ["Representations construct ideas about groups/identities", "Who is shown positively/negatively reflects power relations", "Repetition normalises certain identities", "Can reinforce or challenge existing power structures", "Reference to theory (representation/ideology)", "Evaluative conclusion"], answer: "The way a product represents groups constructs ideas about identity, and which groups are shown positively or given a voice reflects power relations in society. Repeated representations can normalise particular identities and reinforce existing power structures, though products can also challenge them. Representation is therefore not neutral but linked to ideology and power." },
      { g: 9, marks: 6, q: "Evaluate how digital technology has changed the production, distribution and consumption of media.", scheme: ["Production: cheaper/accessible tools → more producers (UGC)", "Distribution: streaming, online, global reach, convergence", "Consumption: on-demand, mobile, interactive, personalised", "Benefits and problems (piracy, misinformation, data)", "Balanced, justified conclusion"], answer: "Digital technology has made production cheaper and more accessible, so many more people can create media; distribution now happens instantly online and globally through streaming and convergence; and consumption is on-demand, mobile, interactive and personalised. This has empowered audiences and producers but also brought piracy, misinformation and data concerns, so its impact is transformative but double-edged." },
      { g: 9, marks: 5, q: "\"Genre is just a marketing tool.\" Evaluate this statement.", scheme: ["For: genre helps market/sell products to known audiences", "Aids audience choice and industry planning", "Against: genre also structures meaning and creativity", "Genres evolve and hybridise (more than marketing)", "Balanced judgement"], answer: "Genre does work as a marketing tool, helping industries target known audiences and helping audiences choose products, which supports the statement. However, genre is more than marketing: it structures meaning, shapes creativity and evolves and hybridises over time. So while marketing is one important function of genre, it is not the only one, making the statement an oversimplification." },
      { g: 9, marks: 6, q: "Evaluate the extent to which audiences are free to interpret media products however they wish.", scheme: ["Active theories: audiences make their own meanings (Hall, U&G)", "Freedom shown by oppositional readings/diverse interpretations", "But producers encode preferred meanings and position audiences", "Context, algorithms and limited access constrain choice", "Balanced, justified conclusion"], answer: "Active-audience theories show audiences do have freedom to make their own meanings, seen in negotiated and oppositional readings and diverse interpretations. However, producers encode preferred meanings and position audiences through media language, and factors like context, personal background, algorithms and limited access constrain what people see and how they read it. So audiences have real but not unlimited freedom to interpret media." },
    ],
    "Forms, products & exam": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What is the title of Component 1 of the Eduqas GCSE Media Studies course?", scheme: ["Exploring the Media"], answer: "Exploring the Media." },
      { g: 4, marks: 1, q: "What is the title of Component 2 of the Eduqas GCSE Media Studies course?", scheme: ["Media Forms and Products"], answer: "Media Forms and Products." },
      { g: 4, marks: 2, q: "State the title of Component 3 and how it is assessed.", scheme: ["Creating Media Products", "Non-exam assessment (NEA)"], answer: "Component 3 is Creating Media Products, and it is assessed as a non-exam assessment (NEA)." },
      { g: 4, marks: 1, q: "What percentage of the GCSE is the non-exam assessment (Component 3)?", scheme: ["30%"], answer: "30%." },
      { g: 4, marks: 1, q: "What is a media brief?", scheme: ["The instructions and requirements a producer must meet"], answer: "A set of instructions and requirements that a media producer must meet." },
      { g: 4, marks: 2, q: "Name the two set magazine covers.", scheme: ["Vogue", "GQ"], answer: "Vogue and GQ." },
      { g: 4, marks: 1, q: "What type of newspaper is The Sun, and what is its political viewpoint?", scheme: ["A right-leaning tabloid"], answer: "The Sun is a right-leaning tabloid newspaper." },
      { g: 4, marks: 1, q: "Which company owns The Sun?", scheme: ["News UK"], answer: "News UK." },
      { g: 4, marks: 2, q: "Name the two set film marketing products.", scheme: ["The Man with the Golden Gun (1974)", "No Time to Die (2021)"], answer: "The Man with the Golden Gun (1974) and No Time to Die (2021)." },
      { g: 4, marks: 1, q: "Which organisation made the 'This Girl Can' advertising campaign?", scheme: ["Sport England"], answer: "Sport England." },
      { g: 4, marks: 1, q: "Name the set video game.", scheme: ["Fortnite"], answer: "Fortnite." },
      { g: 4, marks: 1, q: "What genre of video game is Fortnite?", scheme: ["Online battle royale"], answer: "An online battle royale game." },
      { g: 4, marks: 1, q: "On which radio station are the set radio products broadcast?", scheme: ["BBC Radio 4"], answer: "BBC Radio 4." },
      { g: 4, marks: 2, q: "Name the two television genres that can be studied in Component 2.", scheme: ["Crime drama", "Sitcom"], answer: "Crime drama and sitcom." },
      { g: 4, marks: 2, q: "State two media forms studied in Component 1 Section A.", scheme: ["First form: magazine covers / film posters / newspaper front pages / print adverts", "Second, different form from the same list"], answer: "Magazine covers and film posters (also newspaper front pages and print adverts)." },
      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 2, q: "State the difference between a tabloid and a broadsheet newspaper.", scheme: ["Tabloids are populist / entertainment-led", "Broadsheets are serious / news-led"], answer: "Tabloids are populist and entertainment-led, whereas broadsheets are more serious and led by hard news." },
      { g: 5, marks: 2, q: "Describe what kind of newspaper The Guardian is and its viewpoint.", scheme: ["A 'quality' newspaper run not-for-profit", "Left-liberal viewpoint"], answer: "The Guardian is a 'quality' newspaper run on a not-for-profit basis, with a left-liberal viewpoint." },
      { g: 5, marks: 2, q: "Describe the target audiences of the set magazines Vogue and GQ.", scheme: ["Vogue: a fashion-focused, aspirational audience", "GQ: a men's lifestyle audience"], answer: "Vogue targets a fashion-focused, aspirational audience, while GQ targets a men's lifestyle audience." },
      { g: 5, marks: 2, q: "What is the 'This Girl Can' campaign and what does it set out to challenge?", scheme: ["A Sport England advertising campaign", "Challenges gender stereotypes in sport"], answer: "'This Girl Can' is a Sport England advertising campaign that challenges gender stereotypes in sport." },
      { g: 5, marks: 2, q: "Explain why the Quality Street (1956) advert is useful for studying historical context.", scheme: ["It reflects 1950s gender roles", "It reflects the family values of its time"], answer: "It reflects the gender roles and family values of the 1950s, so it shows how media products are shaped by the society in which they were made." },
      { g: 5, marks: 2, q: "Explain why The Archers is a significant radio product.", scheme: ["It is the world's longest-running radio soap", "It is a BBC public service programme"], answer: "The Archers is the world's longest-running radio soap and is an example of BBC public service broadcasting." },
      { g: 5, marks: 2, q: "Name the two set radio products.", scheme: ["The Archers", "Desert Island Discs"], answer: "The Archers and Desert Island Discs, both on BBC Radio 4." },
      { g: 5, marks: 2, q: "The second topic in Component 2 is music. Which two media forms does it cover?", scheme: ["Music video", "Online media"], answer: "Music video and online media." },
      { g: 5, marks: 2, q: "What is meant by an artist's 'star image'?", scheme: ["A constructed public identity", "Used as a brand to promote the artist"], answer: "A star image is the constructed public identity of an artist, which works as a brand to promote them and their music." },
      { g: 5, marks: 2, q: "State the two main areas assessed in Component 1.", scheme: ["Media language and representation", "Media industries and audiences"], answer: "Media language and representation, plus media industries and audiences." },
      { g: 5, marks: 2, q: "Describe what Component 2 involves.", scheme: ["An in-depth study across the theoretical framework", "Of television and music"], answer: "Component 2 is an in-depth study of television and music across the whole theoretical framework." },
      { g: 5, marks: 2, q: "What is a discursive response in a media exam?", scheme: ["Extended writing exploring media issues", "With a sustained argument"], answer: "An extended piece of writing that explores media issues and develops a sustained argument." },
      { g: 5, marks: 2, q: "Explain why using subject terminology is important in Media Studies exam answers.", scheme: ["Marks are awarded for correct use of media terminology", "It shows precise understanding of how products create meaning"], answer: "Marks are awarded for accurate use of media terminology, and it shows precise understanding of how products create meaning." },
      { g: 5, marks: 3, q: "State three features that make Fortnite a useful example for studying media industries.", scheme: ["Free-to-play", "Cross-platform", "Uses in-game purchases"], answer: "Fortnite is free-to-play, cross-platform and makes money through in-game purchases." },
      { g: 5, marks: 3, q: "State three industry concepts that No Time to Die is studied to show.", scheme: ["Conglomerate ownership", "Convergence", "Cross-media marketing"], answer: "Conglomerate ownership, convergence and cross-media marketing." },
      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Explain why the Component 2 television study compares a contemporary episode with an older extract.", scheme: ["To show how the genre has changed over time", "Changes reflect different social/historical contexts, audiences or technology"], answer: "Comparing them shows how the genre has changed over time, since conventions develop to reflect different social and historical contexts and audiences." },
      { g: 6, marks: 2, q: "Explain how a free-to-play video game such as Fortnite can still make money.", scheme: ["No cost to start playing attracts a very large audience", "Revenue comes from in-game purchases"], answer: "Because it costs nothing to start playing, Fortnite attracts a huge audience, and a proportion of those players spend money on in-game purchases." },
      { g: 6, marks: 2, q: "Explain one benefit to the producer of Fortnite being cross-platform.", scheme: ["It can be played on different devices/platforms", "So it reaches a larger audience and increases potential revenue"], answer: "Being cross-platform means Fortnite can be played on different devices, so it reaches a much larger audience and increases the number of potential paying players." },
      { g: 6, marks: 3, q: "Explain how a newspaper's political viewpoint might influence its front page.", scheme: ["Selection of which stories are given prominence", "Choice of headline language and angle", "Choice of images, shaping the reader's view"], answer: "A newspaper's viewpoint can affect which stories it selects to lead with, the language and angle used in headlines, and the images chosen, all of which construct a version of events that fits its values." },
      { g: 6, marks: 3, q: "Explain how an advertising campaign such as 'This Girl Can' can challenge gender stereotypes in sport.", scheme: ["Stereotype challenged: sport seen as a male domain / women not active in sport", "Represents women as active participants in sport", "Goes against audience expectations to encourage women to take part"], answer: "It challenges the stereotype that sport belongs to men by representing women as active participants, going against audience expectations in order to encourage women to take part themselves." },
      { g: 6, marks: 2, q: "Explain how studying Quality Street (1956) alongside 'This Girl Can' shows that representations of gender change over time.", scheme: ["Quality Street reflects 1950s gender roles and family values", "This Girl Can challenges gender stereotypes, reflecting a later social context"], answer: "Quality Street reflects the gender roles and family values of the 1950s, whereas This Girl Can challenges gender stereotypes, showing how representations change as social attitudes change." },
      { g: 6, marks: 2, q: "Explain why The Archers is an example of public service broadcasting.", scheme: ["Public service broadcasting aims to inform, educate and entertain the public", "The Archers is a long-running BBC programme made to serve the public rather than mainly for profit"], answer: "Public service broadcasting aims to inform, educate and entertain the public; The Archers is a long-running BBC programme made to serve that remit rather than mainly to make a profit." },
      { g: 6, marks: 3, q: "Explain what convergence means, using No Time to Die as an example.", scheme: ["Convergence: media platforms/technologies/industries coming together", "No Time to Die's marketing spread across different media platforms", "This lets the film reach larger and different audiences"], answer: "Convergence is when media platforms, technologies and industries come together. No Time to Die was marketed across many platforms at once, allowing it to reach larger and more varied audiences." },
      { g: 6, marks: 2, q: "Explain why a magazine such as Vogue appeals to an aspirational audience.", scheme: ["Readers desire/aspire to the lifestyle it presents", "This encourages them to buy the magazine and the products it features/advertises"], answer: "Vogue presents a fashionable lifestyle that readers aspire to, which encourages them to buy the magazine and the fashion products it features and advertises." },
      { g: 6, marks: 4, q: "State and explain the four things a top-level Media Studies exam answer should always do.", scheme: ["Use accurate subject terminology", "Apply relevant theory", "Refer to specific media products", "Link to context"], answer: "A top answer uses accurate subject terminology, applies relevant theory, refers closely to specific media products as evidence, and links the analysis to context such as social, historical or industry context." },
      { g: 6, marks: 2, q: "Explain why it is important to follow the brief in the Component 3 production.", scheme: ["The brief sets the requirements the product must meet (e.g. form, audience)", "The product is assessed on how well it meets them"], answer: "The brief sets the requirements, such as the form and target audience, and the production is assessed on how well it meets them." },
      { g: 6, marks: 2, q: "Explain how music video and online media can help promote a music artist.", scheme: ["They construct and reinforce the artist's star image/brand", "They reach audiences across platforms and build fan loyalty"], answer: "Music videos and online media construct and reinforce an artist's star image, reaching audiences across several platforms and building a loyal fan base." },
      { g: 6, marks: 2, q: "Explain how conglomerate ownership can help the marketing of a film such as No Time to Die.", scheme: ["Conglomerates have large budgets/resources", "They can promote the film across many platforms and companies (cross-media marketing)"], answer: "A conglomerate has large budgets and resources, so it can promote a film across many platforms and companies through cross-media marketing." },
      { g: 6, marks: 3, q: "Explain three differences between The Sun and The Guardian.", scheme: ["The Sun is a tabloid; The Guardian is a 'quality' paper", "The Sun is right-leaning; The Guardian is left-liberal", "The Sun is owned by News UK; The Guardian is run not-for-profit"], answer: "The Sun is a tabloid while The Guardian is a 'quality' paper; The Sun is right-leaning while The Guardian is left-liberal; and The Sun is owned by News UK while The Guardian is run not-for-profit." },
      { g: 6, marks: 2, q: "Explain why comparing The Man with the Golden Gun (1974) with No Time to Die (2021) is useful.", scheme: ["They were made decades apart, so show different historical/social contexts", "Shows how marketing, industry practices or representations have changed"], answer: "Made decades apart, the two products reflect different historical and social contexts, so comparing them shows how film marketing, industry practices and representations have changed." },
      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 4, q: "Analyse how a tabloid newspaper front page might use media language to appeal to its audience.", scheme: ["Large, dramatic headlines to grab attention", "Dominant images, often of celebrities or dramatic events", "Informal, emotive or punning language", "Entertainment-led stories suit a populist audience", "Terminology used accurately (e.g. masthead, splash, connotation)"], answer: "A tabloid front page typically uses a large, dramatic headline and a dominant image to grab attention. Informal, emotive language and a focus on entertainment or celebrity stories suit its populist audience, making the paper feel accessible and exciting rather than formal." },
      { g: 7, marks: 4, q: "Analyse how the conventions of a quality or broadsheet newspaper front page reflect its values and audience.", scheme: ["More written text and several stories on the page", "Formal, measured language", "Hard news (politics, economy, international) prioritised", "Images used to inform rather than sensationalise", "Suggests seriousness and credibility for an audience seeking detailed news"], answer: "A quality front page usually carries more text and several stories, written in formal, measured language that prioritises hard news such as politics. Images tend to inform rather than sensationalise, connoting seriousness and credibility for readers who want detailed news." },
      { g: 7, marks: 4, q: "Analyse how Fortnite's business model reflects the contemporary video game industry.", scheme: ["Free-to-play removes the cost barrier to entry", "In-game purchases provide ongoing revenue", "Cross-platform play widens the audience across devices", "Online play keeps audiences returning, increasing chances to spend"], answer: "Being free-to-play removes the cost barrier, so Fortnite builds a huge audience. It then earns ongoing revenue through in-game purchases, while cross-platform, online play widens its reach and keeps players returning, which increases their opportunities to spend." },
      { g: 7, marks: 4, q: "Analyse how the social and historical context of the 1950s shapes the Quality Street (1956) advert.", scheme: ["Media products reflect the values of the time they were made", "The advert reflects 1950s gender roles", "It reflects 1950s family values", "It would have seemed normal to its original audience", "A modern audience may read it differently"], answer: "Media products reflect the values of their time, so the Quality Street advert reflects 1950s gender roles and family values. These representations would have seemed normal to its original audience, but a modern audience may read them differently because attitudes to gender have changed." },
      { g: 7, marks: 4, q: "Analyse how industry and historical context might affect the marketing of The Man with the Golden Gun (1974) compared with No Time to Die (2021).", scheme: ["1974 marketing relied more on traditional forms such as the film poster", "2021 marketing uses convergence and cross-media platforms", "No Time to Die reflects conglomerate ownership and large-scale promotion", "Changing social attitudes may affect representations (e.g. gender)"], answer: "In 1974 film marketing relied more on traditional forms such as the poster, whereas No Time to Die's 2021 campaign reflects convergence, cross-media marketing and conglomerate ownership. Social attitudes also changed over that period, which may affect how representations such as gender are constructed." },
      { g: 7, marks: 4, q: "Analyse how magazine covers such as Vogue and GQ are designed to appeal to different target audiences.", scheme: ["Vogue targets a fashion-focused, aspirational audience", "GQ targets a men's lifestyle audience", "Cover conventions (masthead, cover star, cover lines) are chosen to suit each audience", "Representations may be gendered to match the audience", "Appeal encourages loyalty and sales"], answer: "Vogue targets a fashion-focused, aspirational audience and GQ a men's lifestyle audience, so each uses cover conventions such as the masthead, cover star and cover lines to suit its readers. These choices may construct gendered representations and encourage aspiration, loyalty and sales." },
      { g: 7, marks: 3, q: "Analyse how a newspaper's ownership and viewpoint can shape how it represents events, using The Sun as an example.", scheme: ["The Sun is a right-leaning tabloid owned by News UK", "Selection and construction of stories reflects that viewpoint", "This can reinforce the views of its audience"], answer: "The Sun is a right-leaning tabloid owned by News UK, so its selection and construction of stories, headlines and angles may reflect that viewpoint, which can reinforce the existing views of its readers." },
      { g: 7, marks: 4, q: "Analyse how radio as a form creates meaning in a radio soap such as The Archers.", scheme: ["Radio relies entirely on sound codes", "Dialogue develops characters and relationships", "Sound effects and music establish setting and mood", "Serial narrative with ongoing storylines keeps audiences listening", "Audiences use imagination to build the world"], answer: "Radio relies entirely on sound, so dialogue develops characters and relationships while sound effects and music establish setting and mood. As a soap, it uses an ongoing serial narrative that keeps listeners returning, and audiences use their imagination to build its world." },
      { g: 7, marks: 4, q: "Analyse how the conventions of a television genre such as crime drama or sitcom may change over time.", scheme: ["Identifies typical conventions (e.g. investigation and detectives / recurring characters and familiar setting)", "Changes in social attitudes affect representations (e.g. gender, ethnicity)", "Changes in technology and audience viewing habits affect style and narrative", "Comparing an older extract and a contemporary episode reveals these changes"], answer: "Crime dramas conventionally centre on an investigation, while sitcoms use recurring characters in a familiar setting. Over time, changes in social attitudes alter representations such as gender, and changes in technology and viewing habits affect style and narrative, which is why comparing an older extract with a contemporary episode reveals genre change." },
      { g: 7, marks: 4, q: "Analyse how music videos and online media work together to construct an artist's star image.", scheme: ["Music videos use costume, mise-en-scène and performance to create an identity", "Online media extend that identity across platforms", "Online media allow interaction with fans", "A consistent star image acts as a brand that sells music"], answer: "Music videos use costume, mise-en-scène and performance to construct an artist's identity, while online media extend it across platforms and let the artist interact with fans. Kept consistent, this star image works as a brand that helps sell the music." },
      { g: 7, marks: 4, q: "Analyse how the 'This Girl Can' campaign uses representation to target its audience.", scheme: ["Challenges gender stereotypes in sport", "Represents women as active participants in sport", "Encourages identification from women in the target audience", "Aims to change behaviour (participation) rather than sell a product, as a Sport England campaign"], answer: "As a Sport England campaign, This Girl Can challenges gender stereotypes in sport by representing women as active participants. This encourages women in the audience to identify with the people shown, and its aim is to persuade them to take part in sport rather than to sell a product." },
      { g: 7, marks: 3, q: "Analyse why a big-budget film such as No Time to Die uses cross-media marketing.", scheme: ["A big-budget conglomerate film needs a very large audience to make a profit", "Cross-media marketing reaches different audiences across platforms", "Convergence allows promotion to be coordinated across these platforms"], answer: "A big-budget film owned by a conglomerate needs a very large audience to be profitable, so cross-media marketing uses convergence to coordinate promotion across many platforms and reach different audiences." },
      { g: 7, marks: 5, q: "Analyse one key convention of each of the four forms in Component 1 Section A and how it communicates with audiences.", scheme: ["Magazine covers: e.g. masthead or cover lines establish brand/content", "Film posters: e.g. title, tagline or central image signal genre", "Newspaper front pages: e.g. headline and main image show the lead story", "Print adverts: e.g. slogan, logo or product image persuade", "Links each convention to its effect on the audience"], answer: "On magazine covers, the masthead establishes the brand; on film posters, the central image and title signal genre; on newspaper front pages, the headline and main image mark the lead story; and in print adverts, the logo and slogan persuade. Each convention quickly tells the audience what the product is and why it should interest them." },
      { g: 7, marks: 4, q: "Analyse how a student can move from description to analysis in a Media Studies exam answer.", scheme: ["Identify a feature using accurate terminology", "Explain its connotations and effect", "Apply relevant theory", "Link to audience and context"], answer: "Rather than only describing, a student should identify a feature using accurate terminology, explain its connotations and effect, apply relevant theory, and link the point to the audience and context." },
      { g: 7, marks: 3, q: "Analyse how Fortnite's online battle royale genre encourages audiences to keep playing.", scheme: ["Competitive format where players compete to be the last one remaining", "Online play is social, connecting players with others", "Short, repeatable matches encourage repeat play and more opportunities for in-game purchases"], answer: "The battle royale format is competitive, with players fighting to be the last one remaining, and online play makes it social. Short, repeatable matches encourage players to keep returning, giving more opportunities for in-game purchases." },
      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 5, q: "Analyse how the different ownership and viewpoints of The Sun and The Guardian may affect their newspaper front pages.", scheme: ["The Sun: right-leaning tabloid owned by News UK", "The Guardian: left-liberal 'quality' paper run not-for-profit", "Viewpoint influences selection of stories and angle", "Tabloid conventions (populist, entertainment-led) vs quality conventions (serious, news-led)", "Each constructs a version of events that appeals to its readers' values", "Commercial vs not-for-profit ownership may influence priorities"], answer: "The Sun is a right-leaning tabloid owned by News UK, while The Guardian is a left-liberal 'quality' paper run not-for-profit. Their viewpoints influence which stories are selected and the angle taken, and their forms differ: The Sun is populist and entertainment-led, The Guardian more serious and news-led. Each front page constructs a version of events that matches its readers' values, and different ownership models may shape their priorities." },
      { g: 8, marks: 5, q: "Analyse how social and historical contexts influence the representation of gender in the Quality Street (1956) advert and the 'This Girl Can' campaign.", scheme: ["Representations reflect the values of their time", "Quality Street reflects 1950s gender roles and family values", "This Girl Can challenges gender stereotypes in sport", "The difference reflects changing social attitudes to gender", "Different purposes: selling a product vs a Sport England campaign"], answer: "Representations reflect the values of their time. Quality Street reflects 1950s gender roles and family values, whereas This Girl Can, a Sport England campaign, challenges gender stereotypes in sport. The contrast shows how social attitudes to gender have changed, though the products also have different purposes: one sells a product and the other encourages participation." },
      { g: 8, marks: 5, q: "Analyse how media industry contexts differ for the marketing of The Man with the Golden Gun (1974) and No Time to Die (2021).", scheme: ["No Time to Die reflects conglomerate ownership", "2021 marketing uses convergence across platforms", "Cross-media marketing reaches global and varied audiences", "1974 marketing had fewer platforms and relied more on traditional forms such as posters", "Technological change has transformed how films are promoted"], answer: "No Time to Die was marketed in a context of conglomerate ownership and convergence, using cross-media marketing to reach global, varied audiences. In 1974 there were far fewer platforms, so marketing relied more on traditional forms such as the film poster. Technological and industry change has therefore transformed how films are promoted." },
      { g: 8, marks: 4, q: "Analyse how Fortnite's free-to-play model affects the relationship between the producer and its audience.", scheme: ["Audience gains access without paying up front", "Producer's revenue depends on continued engagement and in-game purchases", "Audiences are active users who choose whether and what to buy", "Raises issues about encouraging spending, especially among young players"], answer: "Players can join without paying, but the producer's revenue depends on keeping them engaged so they make in-game purchases. Audiences are active users who choose whether to spend, yet the model raises concerns about encouraging spending, particularly among younger players." },
      { g: 8, marks: 4, q: "Analyse how the BBC's public service status influences radio products such as The Archers.", scheme: ["Public service remit to inform, educate and entertain", "Less reliance on commercial pressures allows long-running programmes", "The Archers is the world's longest-running radio soap", "Aims to serve a broad public audience rather than maximise profit"], answer: "The BBC's public service remit is to inform, educate and entertain, and because it is less driven by commercial pressures it can sustain programmes like The Archers, the world's longest-running radio soap. Its aim is to serve the public rather than simply to maximise profit." },
      { g: 8, marks: 5, q: "Analyse how magazine covers aimed at gendered audiences, such as Vogue and GQ, may construct representations of gender.", scheme: ["Vogue targets a fashion-focused, aspirational audience", "GQ targets a men's lifestyle audience", "Selection of cover star, pose, costume and cover lines constructs gender", "Representations may reinforce ideals of femininity or masculinity", "Representations are constructed to appeal to and flatter the target audience", "Audiences may accept, negotiate or reject these representations"], answer: "Vogue targets a fashion-focused, aspirational audience and GQ a men's lifestyle audience, so the selection of cover star, pose, costume and cover lines constructs versions of femininity and masculinity designed to appeal to each. These may reinforce idealised gender norms, though audiences may accept, negotiate or reject them." },
      { g: 8, marks: 4, q: "Analyse how comparing a contemporary television episode with an older extract shows that genres are dynamic.", scheme: ["Some core conventions remain recognisable", "Other conventions develop or are subverted over time", "Changes reflect social and historical context (e.g. representation)", "Changes reflect industry, technology and audience expectations"], answer: "Comparing the two shows that some core conventions stay recognisable while others develop or are subverted. These changes reflect shifts in social context, such as representation, as well as changes in industry, technology and audience expectations, showing genre is dynamic rather than fixed." },
      { g: 8, marks: 5, q: "Analyse how convergence has changed the way music artists reach audiences through music video and online media.", scheme: ["Convergence brings platforms and technologies together", "Music videos can be shared and viewed online", "Online media allow artists to communicate directly with fans", "Star image can be reinforced consistently across platforms", "Audiences become active, sharing and responding to content"], answer: "Convergence brings platforms together, so music videos are now shared and watched online, and artists can communicate directly with fans through online media. This lets them reinforce a consistent star image across platforms, while audiences become more active by sharing and responding to content." },
      { g: 8, marks: 4, q: "Analyse how the brief shapes the decisions a student makes when creating their Component 3 production.", scheme: ["Sets the media form and requirements", "Specifies the target audience, affecting representation and style", "Requires use of appropriate codes and conventions", "Linked to the theoretical framework, e.g. industry context"], answer: "The brief sets the media form and requirements, and specifies the target audience, which affects representation and style. The student must use appropriate codes and conventions and show understanding of the theoretical framework, including industry context." },
      { g: 8, marks: 4, q: "Analyse how a magazine such as Vogue uses its covers to sustain an aspirational appeal.", scheme: ["Targets a fashion-focused, aspirational audience", "Cover conventions such as the masthead and cover star connote glamour and status", "Readers are positioned to desire the lifestyle shown", "Aspiration supports sales and advertising revenue"], answer: "Vogue targets a fashion-focused, aspirational audience, so cover conventions such as the masthead and cover star connote glamour and status. Readers are positioned to desire this lifestyle, which supports magazine sales and makes it attractive to advertisers." },
      { g: 8, marks: 5, q: "Analyse how different audiences might interpret the 'This Girl Can' campaign.", scheme: ["Preferred reading: accepts its challenge to gender stereotypes in sport", "Negotiated reading: agrees in part but questions aspects", "Oppositional reading: rejects the message", "Audience factors such as gender, age or interest in sport influence readings", "Audiences are active in making meaning"], answer: "Many audiences may take the preferred reading and accept its challenge to gender stereotypes in sport. Others may take a negotiated reading, agreeing in part but questioning aspects, or an oppositional reading that rejects the message. Factors such as gender, age and interest in sport influence this, showing audiences actively make meaning." },
      { g: 8, marks: 4, q: "Analyse how a tabloid's populist approach reflects both its target audience and its commercial aims.", scheme: ["Entertainment-led, accessible content appeals to a broad audience", "Dramatic headlines and images attract attention", "Wide appeal maximises sales", "Large audiences attract advertising revenue"], answer: "A tabloid uses entertainment-led, accessible content with dramatic headlines and images to appeal to a broad audience. This wide appeal is commercially important because it maximises sales and attracts advertisers." },
      { g: 8, marks: 4, q: "Analyse why an online video game such as Fortnite raises issues for regulation.", scheme: ["Popular with younger audiences, so age ratings matter", "In-game purchases raise concerns about spending", "Online interaction with strangers raises safety concerns", "Global, cross-platform online products are harder to regulate"], answer: "Fortnite is popular with younger players, so age ratings matter, while in-game purchases raise concerns about spending and online interaction raises safety issues. Because it is global, online and cross-platform, it is also harder to regulate than traditional media." },
      { g: 8, marks: 4, q: "Analyse how a radio soap such as The Archers maintains audience loyalty over a long period.", scheme: ["Serial narrative with ongoing storylines", "Familiar characters audiences become attached to", "Regular scheduling builds listening habits", "Storylines can reflect contemporary issues to stay relevant"], answer: "A radio soap uses an ongoing serial narrative with familiar characters that listeners become attached to. Regular scheduling builds listening habits, and storylines can reflect contemporary issues so it stays relevant across generations." },
      { g: 8, marks: 5, q: "Analyse how context should be used to strengthen an exam answer about a set product.", scheme: ["Identify the relevant context (social, cultural, historical, political or industry)", "Link context to specific choices in the product", "Explain how context shapes representations or media language", "Consider how audiences in different contexts read the product", "Use terminology and theory alongside context"], answer: "A strong answer identifies the relevant context — social, historical, political or industry — and links it to specific choices in the product, explaining how it shapes representations or media language. It also considers how audiences in different contexts might read the product, using terminology and theory alongside." },
      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Evaluate how far The Sun and The Guardian show that ownership and viewpoint shape news content.", scheme: ["The Sun: right-leaning tabloid owned by News UK", "The Guardian: left-liberal 'quality' paper run not-for-profit", "Viewpoint influences selection and construction of stories", "Commercial ownership may prioritise sales and populist content", "Not-for-profit model may allow different priorities", "Counter-argument: audience demand and form (tabloid/quality) also shape content", "Reaches a supported judgement"], answer: "The two papers suggest ownership and viewpoint strongly shape content: The Sun, a right-leaning tabloid owned by News UK, and The Guardian, a left-liberal paper run not-for-profit, select and construct stories that fit their values. Commercial ownership may push populist, sales-driven content, while a not-for-profit model allows different priorities. However, content is also shaped by the audience each paper serves and by the conventions of its form, so ownership is an important influence but not the only one." },
      { g: 9, marks: 6, q: "Evaluate the view that media products reflect society's attitudes rather than shape them, referring to Quality Street (1956) and 'This Girl Can'.", scheme: ["Quality Street reflects 1950s gender roles and family values", "Supports the view that products reflect their context", "This Girl Can challenges gender stereotypes in sport", "Suggests media can try to shape attitudes and behaviour", "Even reflective products may reinforce norms by presenting them as normal", "Reaches a balanced judgement"], answer: "Quality Street reflects 1950s gender roles and family values, supporting the view that media mirror their context. However, by presenting those roles as normal it may also have reinforced them. This Girl Can deliberately challenges gender stereotypes in sport, showing media can try to shape attitudes and behaviour. Overall, media both reflect and shape society, and the balance depends on the product's purpose and context." },
      { g: 9, marks: 6, q: "Evaluate whether the conglomerate ownership behind No Time to Die benefits audiences as well as producers.", scheme: ["Conglomerates have large budgets and resources", "Cross-media marketing and convergence give wide reach and profit", "Audience benefit: high production values and easy access across platforms", "Drawback: concentrated ownership may reduce diversity of products", "Drawback: audiences are heavily targeted by marketing", "Reaches a supported judgement"], answer: "Conglomerate ownership clearly benefits producers, giving the resources for cross-media marketing and convergence that maximise reach and profit. Audiences may benefit from high production values and easy access across platforms. However, concentrated ownership can reduce the diversity of products and leaves audiences heavily targeted by marketing. On balance, producers gain most, though audiences gain some benefits too." },
      { g: 9, marks: 6, q: "Evaluate the free-to-play model used by Fortnite for both the industry and its audiences.", scheme: ["Free-to-play attracts a vast audience", "Cross-platform play extends reach", "In-game purchases generate ongoing revenue", "Audiences benefit from free access and social play", "Concerns about pressure to spend, especially for young players", "Regulatory challenges", "Reaches a supported judgement"], answer: "For the industry, free-to-play is highly effective: it attracts a vast, cross-platform audience and earns ongoing revenue from in-game purchases. Audiences benefit from free access and social play, but the model can create pressure to spend, especially for young players, and is difficult to regulate. Overall it is a commercial success, but its benefits to audiences are more mixed." },
      { g: 9, marks: 5, q: "Evaluate the importance of public service broadcasting in today's media landscape, referring to the set BBC Radio 4 products.", scheme: ["PSB aims to inform, educate and entertain", "The Archers is the world's longest-running radio soap and a BBC public service programme", "Less commercial pressure allows long-running or specialist content such as The Archers and Desert Island Discs", "Challenge: competition from commercial and online media", "Reaches a supported judgement"], answer: "Public service broadcasting aims to inform, educate and entertain. Less commercial pressure allows the BBC to sustain products like The Archers, the world's longest-running radio soap, and Desert Island Discs on Radio 4. Although competition from commercial and online media is intense, PSB remains important because it offers content that may not survive on profit alone." },
      { g: 9, marks: 6, q: "Evaluate how far magazine covers aimed at gendered audiences, such as Vogue and GQ, reinforce rather than challenge gender stereotypes.", scheme: ["Vogue targets a fashion-focused, aspirational audience; GQ a men's lifestyle audience", "Targeting by gender can encourage traditional ideals of femininity and masculinity", "Aspirational representations may present idealised, narrow images", "Covers can also challenge stereotypes through choice of cover star or cover lines", "Audiences may negotiate or reject representations", "Reaches a supported judgement"], answer: "Because Vogue targets a fashion-focused, aspirational audience and GQ a men's lifestyle audience, their covers may encourage traditional, idealised versions of femininity and masculinity. However, choices of cover star and cover lines can also challenge stereotypes, and audiences may negotiate or reject these representations. Overall, gendered targeting makes reinforcement likely, but covers are capable of challenging stereotypes too." },
      { g: 9, marks: 6, q: "'Television genres never stay the same.' Evaluate this statement with reference to crime drama or sitcom.", scheme: ["Genres have recognisable core conventions that persist", "Conventions develop in response to social and historical context", "Representations change as social attitudes change", "Technology and audience habits change style and narrative", "Comparison of older extract and contemporary episode as evidence", "Reaches a judgement: genres are dynamic but keep core conventions"], answer: "Comparing an older extract with a contemporary episode shows genres do change: representations shift as social attitudes change, and technology and viewing habits alter style and narrative. However, core conventions — such as an investigation in crime drama or recurring characters in a familiar setting in sitcom — persist, otherwise the genre would not be recognisable. Genres are therefore dynamic, but they never change completely." },
      { g: 9, marks: 6, q: "Evaluate how important star image is to the success of music artists in a converged media landscape.", scheme: ["Star image is a constructed public identity/brand", "Music videos construct identity through costume, mise-en-scène and performance", "Online media extend the image and build fan relationships", "A strong brand helps sell music and related products", "Counter-argument: the music itself and industry support also matter", "Reaches a supported judgement"], answer: "Star image is a constructed identity that works as a brand. Music videos build it through costume, mise-en-scène and performance, and online media extend it while building relationships with fans, helping to sell music. However, the quality of the music and industry support also matter. Overall, in a converged landscape star image is extremely important, but it works alongside these other factors." },
      { g: 9, marks: 5, q: "Evaluate the most effective approach to writing a top-level discursive response in the exam.", scheme: ["Plan a clear, sustained argument", "Use accurate subject terminology throughout", "Apply relevant theory", "Support points with close reference to set products", "Link to context and reach a justified conclusion"], answer: "The most effective approach is to plan a clear, sustained argument rather than a list of points. Each point should use accurate terminology, apply relevant theory and refer closely to set products, while linking to context. Ending with a justified conclusion shows the evaluation that top-level answers require." },
      { g: 9, marks: 5, q: "Evaluate the claim that audiences of online media and video games are more active than audiences of older media.", scheme: ["Fortnite players make choices, compete and interact online", "Online media let music fans comment, share and interact with artists", "Older media audiences were also active in interpreting meaning", "Online audiences are still shaped by producers, e.g. in-game purchase design", "Reaches a supported judgement"], answer: "Fortnite players make choices and interact online, and music fans can share content and communicate with artists, suggesting greater activity. However, audiences of older media also actively interpreted meaning, and online audiences are still shaped by producers, for example through in-game purchase design. Online audiences have more ways to participate, but they are not necessarily more in control." },
      { g: 9, marks: 6, q: "Compare how print forms from Component 1 Section A and digital forms such as video games and online media engage their audiences.", scheme: ["Print forms (magazine covers, film posters, newspaper front pages, print adverts) use visual and written codes", "Print audiences engage by reading and interpreting a fixed text", "Fortnite engages through interactive, social, cross-platform play", "Online media allow sharing, comment and direct contact with artists", "Both rely on codes and conventions and target specific audiences", "Reaches a judgement on similarities and differences"], answer: "Print forms such as magazine covers and newspaper front pages use visual and written codes that audiences read and interpret as fixed texts. Digital forms are more interactive: Fortnite engages players through social, cross-platform play, and online media let fans share and communicate with artists. Both still rely on codes and conventions to target specific audiences, but digital forms offer far greater participation." },
      { g: 9, marks: 5, q: "Evaluate why analysis of media language alone is not enough for a top-grade exam answer.", scheme: ["Media language analysis explains how meaning is created", "Top answers also apply theory", "Context explains why products are made as they are", "Audience and industry factors deepen the analysis", "Reaches a judgement that the full theoretical framework is needed"], answer: "Analysing media language explains how meaning is created, but top answers go further by applying theory and linking to context, which explains why a product was made that way. Considering audiences and industries deepens the argument, so the full theoretical framework is needed for the highest marks." },
      { g: 9, marks: 6, q: "Evaluate how far advertising can be a force for social change, referring to 'This Girl Can' and Quality Street (1956).", scheme: ["This Girl Can is a Sport England campaign challenging gender stereotypes in sport", "Its aim is to change attitudes and behaviour rather than sell a product", "Quality Street reflects 1950s gender roles and family values", "Commercial adverts often reinforce dominant values to sell products", "Audiences may not accept the preferred reading", "Reaches a supported judgement"], answer: "This Girl Can shows advertising can aim for social change, as a Sport England campaign that challenges gender stereotypes to change behaviour rather than sell a product. By contrast, Quality Street reflects 1950s gender roles and family values, suggesting commercial adverts often reinforce dominant values. As audiences may not accept the intended message, advertising can contribute to social change but cannot guarantee it." },
      { g: 9, marks: 5, q: "Evaluate what makes a Component 3 production successful.", scheme: ["Meets all requirements of the brief", "Uses codes and conventions of the form effectively", "Clearly targets and appeals to the specified audience", "Shows understanding of the theoretical framework, e.g. representation and industry", "Reaches a judgement on the most important factor"], answer: "A successful production meets every requirement of the brief, uses the codes and conventions of its form effectively and clearly appeals to the specified audience. It also shows understanding of the framework, such as representation and industry. Meeting the brief matters most, because the other qualities are judged against it." },
      { g: 9, marks: 6, q: "Evaluate whether tabloid or quality newspapers better serve their audiences, referring to The Sun and The Guardian.", scheme: ["The Sun is a right-leaning, populist, entertainment-led tabloid owned by News UK", "The Guardian is a left-liberal, serious, news-led quality paper run not-for-profit", "Tabloids serve audiences through accessibility and entertainment", "Quality papers serve audiences through detailed news", "Both are shaped by a political viewpoint, so neither is neutral", "Uses the idea of audience needs to judge", "Reaches a supported judgement"], answer: "The Sun, a right-leaning tabloid owned by News UK, serves its audience through accessible, entertainment-led content, while The Guardian, a left-liberal quality paper run not-for-profit, offers more detailed, news-led coverage. Both construct news from a political viewpoint, so neither is neutral. Which serves audiences better depends on their needs: tabloids meet a need for entertainment, while quality papers better meet a need for information." },
    ],
  },
}
